//! Replays of live GNU evidence for the primitives (crates/romacs-vm/tools/primh):
//! the harness is tools/primh/replay.rs.in, rendered for this crate when the
//! test builds (romacs-vm-test-build). Each test replays one primitive's
//! recording against its spec; live GNU is not needed to run them.
romacs_vm_test_build::primh_harness!();

